import{j as e,c as m,ab as oe,cy as g,cz as f,cA as v,cB as b,aF as E,E as T,D as d,cC as $,cD as x,cE as i,o as A,C as u,R as N,f as w,cF as _,H as se,O as S,g as l,h as O,cG as j,i as c,cH as k,k as R,l as te,N as D,cI as M,m as q,ca as C,cc as P,e as I,cJ as U,cK as L,cL as H,T as F,G as B,F as G,cM as z,n as Y,cN as V,cO as W,M as ne,b as ie,p as re}from"./index-NMHuTXpc.js";import{r as de}from"./vendor-sonner-BFkWhx6y.js";import{g as X}from"./guildCopy-BmA379NR.js";import"./vendor-DDxydHEc.js";import"./vendor-capacitor-B8vh4tkU.js";function pe({isOpen:Q,onClose:K,language:r="en-US"}){const J=r==="pt-BR",a=(t,n)=>J?t:n,[Z,ee]=de.useState(null),s=oe,[,,h]=se,p=Math.round(re*u),y=te.length,o={...m,margin:0},ae=[{id:"evolve",title:a("Como seu Soulmon evolui","How it evolves"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a("Cada forma tem uma barra: o caminho até a próxima. Todo hábito ou tarefa concluída é um passo — tarefas maiores valem mais (1 a 3) — e o dia soma no máximo a meta diária do estágio. A barra entra na virada do dia e nunca volta para trás.","Each form has a bar: the path to the next one. Every habit or task you finish is a step — bigger tasks count more (1 to 3) — and a day adds at most your stage’s daily goal. The bar fills at the turn of the day and never goes back.")}),e.jsx("p",{style:o,children:a(`Rookie→Champion pede ${s.rookie.gauge} passos (até ${s.rookie.required} por dia); Champion→Ultimate ${s.champion.gauge} (até ${s.champion.required}/dia); Ultimate→Mega ${s.ultimate.gauge} (até ${s.ultimate.required}/dia).`,`Rookie→Champion takes ${s.rookie.gauge} steps (up to ${s.rookie.required} a day); Champion→Ultimate ${s.champion.gauge} (up to ${s.champion.required}/day); Ultimate→Mega ${s.ultimate.gauge} (up to ${s.ultimate.required}/day).`)}),e.jsx("p",{style:o,children:a(`O Ultra tem dois caminhos: ${g} passos como mega, ou conhecer os três galhos (aí bastam ${s.mega.gauge}). Nenhum é melhor, e nenhum pede que você degenere.`,`The Ultra has two paths: ${g} steps as a mega, or knowing all three branches (then ${s.mega.gauge} is enough). Neither is better, and neither asks you to degenerate.`)}),e.jsx("p",{style:o,children:a("Depois do Ultra existe o Renascimento, para quem tem a conta completa: sua criatura vira ovo, volta a Rookie e os atributos zeram — em troca ela nasce mais funda e você escolhe a criatura, a escola e o elemento dela. Bits, cenários, sonhos, hábitos e o caminho andado continuam intactos. Acontece uma vez só.","After the Ultra comes Rebirth, for full accounts: your creature becomes an egg, returns to Rookie and attributes reset — in exchange they are born deeper and you choose their creature, school and element. Bits, scenes, dreams, habits and the path walked stay intact. It happens only once.")}),e.jsx("p",{style:o,children:a("O caminho só acumula — um dia fraco soma pouco, nunca tira. Dia completo (a meta do dia inteira) é um selo do dia: rende Bits, mas não é mais o que faz evoluir. A evolução é sua: toque no Soulmon na página de Evolução para travar ou destravar o cadeado.","The path only accumulates — a light day adds a little, never takes away. A complete day (the whole daily goal) is a seal for the day: it pays Bits, but it is no longer what makes it evolve. Evolution is yours to trigger: tap your Soulmon on the Evolution page to lock or unlock the padlock.")}),e.jsx("p",{style:o,children:a("Quando a barra enche, a próxima forma começa a tomar corpo: leva um tempo até ficar pronta. Volte quando quiser — ela espera por você, e nada se perde no caminho.","When the bar fills, the next form starts taking shape: it takes a while to be ready. Come back whenever you like — it waits for you, and nothing is lost along the way.")})]})},{id:"hearts",title:a("Corações","Hearts"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Na virada do dia você perde no máximo ${f} coração, proporcional ao que ficou por fazer. Cumpriu a meta, não perde nada.`,`At the day turn you lose at most ${f} heart, in proportion to what you left undone. Meet the goal and you lose nothing.`)}),e.jsx("p",{style:o,children:a(`Sumiu por ${v} dias ou mais? Voltar não custa nada. Toda segunda seu Soulmon recupera ${b} coração. Quando um dia não custa nada, o relatório diário conta qual pausa segurou.`,`Away for ${v} days or more? Coming back costs nothing. Every Monday it recovers ${b} of a heart. When a day costs nothing, the daily report says which pause held it.`)}),e.jsx("p",{style:o,children:a("Cocô não limpo drena 1 coração a cada 6 horas — dê banho. Esfregar o pet é o principal jeito de curar (até 1 coração por dia). Se zerar, seu Soulmon regride uma forma.","Uncleaned poop drains 1 heart every 6 hours — give it a bath. Rubbing your pet is the main way to heal (up to 1 heart a day). At zero it degenerates one form.")})]})},{id:"care",title:a("Comida e energia","Food and energy"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`As barras de energia são o dobro da meta diária do estágio (Rookie: ${E("rookie")}). Ela sobe com o tempo (1 a cada ${T} min com o Soulmon bem alimentado, a metade da velocidade com um pouco de fome, parada se ele estiver faminto) e zera todo dia — e não decide o dia completo. Ela serve para descer a Masmorra: cada camada gasta ${d}, e subir de nível enche de novo.`,`Energy bars are twice your stage’s daily goal (Rookie: ${E("rookie")}). It rises with time (1 every ${T} min when your Soulmon is well fed, half speed when a little hungry, stopped when starving) and resets daily — and does not decide the complete day. It is what the Dungeon runs on: each layer spends ${d}, and leveling up refills it.`)}),e.jsx("p",{style:o,children:a(`Cada tarefa concluída rende uma comida. Alimentar enche a fome (que cai em ${$} h do cheio ao vazio) e dá pontos de atributo — que definem o galho da evolução —, mas NÃO dá energia direto e NÃO cura coração. Fome não custa nada além da energia parada. Até ${x} vezes por hora.`,`Each completed task yields one food. Feeding fills hunger (which drops from full to empty in ${$} h) and grants attribute points — which steer your evolution branch — but does NOT give energy directly and does NOT heal hearts. Hunger costs nothing beyond paused energy. Up to ${x} times an hour.`)}),e.jsx("p",{style:o,children:a(`Depois do café, do almoço e do jantar (${i.breakfast}, ${i.lunch} e ${i.dinner}, nas Configurações você muda), seu Soulmon pode pedir UMA coisa pequena por ${A/60} horas: um carinho, um banho, uma comidinha. Não vale pontos, não conta e pular não custa nada. Os lembretes começam desligados.`,`After breakfast, lunch and dinner (${i.breakfast}, ${i.lunch} and ${i.dinner} — change them in Settings), your Soulmon may ask for ONE small thing for ${A/60} hours: a pat, a rinse, a snack. It earns no points, nothing is counted, and skipping costs nothing. The reminders start off.`)})]})},{id:"habits",title:a("Hábitos","Habits"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Não existe sequência que zera. O que aparece é a constância: "${p} das últimas ${u}". Uma falta custa uma fatia, nunca tudo.`,`There is no streak that resets. What you see is consistency: "${p} of the last ${u}". A missed day costs a slice, never everything.`)}),e.jsx("p",{style:o,children:a(`A cada ${N} dias de boa constância você ganha um escudo (até ${w}). Ele é gasto sozinho no dia em que você falta — nada para lembrar de ativar.`,`Every ${N} days of good consistency you earn a shield (up to ${w}). It is spent automatically on a day you miss — nothing to remember to switch on.`)}),e.jsx("p",{style:o,children:a(`Uma falta não gera nada. Em ${_} seguidas, o pet oferece uma versão bem menor do hábito — aceitar já conta como feito. E o ícone amadurece até virar árvore em ${h} dias feitos, rendendo mais atributo.`,`One miss does nothing. At ${_} in a row, your pet offers a much smaller version of the habit — accepting counts as done. And the icon matures into a tree at ${h} days done, yielding more attribute.`)})]})},{id:"tasks",title:a("Tarefas","Tasks"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a('Hábito é o que acontece TODO DIA e aparece sempre no Hoje; tarefa é pontual ou em dias específicos, configurada por você (só aparece nos dias dela; a lista completa fica em "Ver tudo"). Tarefa com subitens pesa pelo esforço que você escolheu, nunca pelo número de subitens: cada subitem feito avança a barra e rende um pouquinho de XP (até 5 subitens por tarefa, no máximo +50% do XP dela), e o peso nunca passa do que as mesmas tarefas soltas pesariam (máximo 3). Fechar TODOS os subitens de uma tarefa com 3 ou mais rende uma comida premium (★): 5 de energia em vez de 1, no máximo uma por dia e três por semana, sem passar do máximo do dia. O check de um hábito vale só para o dia de hoje; o "N de M" ao lado é só o resumo da semana.',`A habit happens EVERY DAY and always shows in Today; a task is one-off or on specific days, set up by you (it only shows on its days; the full list lives in "View all"). A task with steps weighs by the effort you picked, never by how many steps it has: each finished step advances the bar and earns a little XP (up to 5 steps per task, at most +50% of its XP), and the weight never exceeds what the same loose tasks would (max 3). Finishing ALL steps of a task with 3 or more earns a premium food (★): 5 energy instead of 1, at most one a day and three a week, never above the day's max. A habit's check counts for for that day; the "N of M" beside it is just the week's summary.`)}),e.jsx("p",{style:o,children:a(`Toda tarefa tem um esforço: Rápida (1), Média (2) ou Projeto (3). A meta soma esforço, não itens — um Projeto vale três Rápidas. Passando de ${S} pontos no dia, o pet avisa. É aviso, nunca bloqueio.`,`Every task has an effort: Quick (1), Medium (2) or Project (3). The goal adds up effort, not items — one Project is worth three Quick ones. Past ${S} points in a day your pet says so. A heads-up, never a block.`)}),e.jsx("p",{style:o,children:a(`No check-in você escolhe até ${l} focos do dia; completar os ${l} rende o selo.`,`At check-in you pick up to ${l} focus tasks; completing all ${l} earns the seal.`)}),e.jsx("p",{style:o,children:a(`Parada há ${O} dias ela fica assombrada — e concluir uma assombrada dá bônus de alívio. Adiada ${j} vezes, o pet oferece dividir, encolher ou deixar pra lá.`,`Untouched for ${O} days it becomes haunted — and clearing a haunted task grants a relief bonus. Postponed ${j} times, your pet offers to split it, shrink it or let it go.`)}),e.jsx("p",{style:o,children:a('"Algum dia" é permissão formal para não fazer agora: não conta na meta e não assombra. "Deixar pra lá" é um fim honesto, com volta atrás.',`"Someday" is formal permission not to do it now: it doesn't count toward the goal and never haunts. "Let it go" is an honest ending, with an undo.`)})]})},{id:"rest",title:a("Descanso e sonhos","Rest and dreams"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a(`Você escolhe a SUA janela de sono (padrão ${c.start}–${c.end}, com ${k} min de tolerância). O que conta é o gesto de deitar no horário — nunca a qualidade do seu sono.`,`You choose YOUR own sleep window (default ${c.start}–${c.end}, with ${k} min of grace). What counts is going to bed on time — never how well you slept.`)}),e.jsx("p",{style:o,children:a(`Sem nota de sono e sem castigo: noite sem registro é neutra. A leitura é quantas das últimas ${R} noites entraram na janela.`,`No sleep score and no penalty: an unlogged night is neutral. The reading is how many of the last ${R} nights landed inside the window.`)}),e.jsx("p",{style:o,children:a(`Cada noite na janela seu Soulmon SONHA, e o sonho é uma cena colecionável do próprio Soulmon — ${y} para descobrir. A raridade vem da regularidade, nunca de dormir mais. Uma noite no horário também traz ${D} de energia a mais de manhã, uma vez por dia; sem noite, nada se perde.`,`Every night inside the window it DREAMS, and the dream is a collectible scene of itself — ${y} to discover. Rarity comes from regularity, never from sleeping longer. A night on time also brings ${D} extra energy in the morning, once a day; no night, nothing is lost.`)})]})},{id:"passeio",title:a("Passeio e Travessias","Stroll and Crossings"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a("Na Exploração fica o Passeio: seu Soulmon sai todo dia e conta o que viu no relatório do fim do dia. Você escolhe para onde — casa ou uma região já aberta.","The Stroll lives in Exploration: your Soulmon heads out every day and tells you what it saw in the end-of-day report. You pick where — home, or a region that is already open.")}),e.jsx("p",{style:o,children:a("Travessias são opcionais: algo que você faz na sua vida, fora do app, sempre com uma versão pequena para fazer em casa. O passeio fica com o NPC da Exploração: é lá que você escolhe e conclui. Ficam esperando o tempo que for, e deixar pra lá não custa nada. Um passeio leva um tempo: depois de pegar a missão, o Concluir abre em "+M+' minutos. No menu de Missões da Home fica só a linha "Faça um passeio". As missões só apontam o que fazer; quando a ação acontece (um registro no journaling, o passeio concluído no NPC), a linha fica pronta e você toca em Resgatar. Há dois acessos na Home: missões diárias e missões semanais. Quando você resgata, a névoa de uma região se abre no passeio da noite seguinte.',"Crossings are optional: something you do in your own life, outside the app, always with a small version you can do at home. The stroll stays with the NPC in Exploration: that is where you pick and finish it. It waits as long as you like, and letting one go costs nothing. A stroll takes a little while: once you pick a mission, Done opens after "+M+` minutes. The Missions menu on Home only keeps a "Take a stroll" line. Missions only point at what to do; once the action happens (an entry in your journal, the stroll finished at the NPC), the line turns ready and you tap Claim. Home has two doors: daily missions and weekly missions. Once you claim, the mist over a region clears on the next night's stroll.`)}),e.jsx("p",{style:o,children:a("Nada disso mexe no seu Soulmon, na meta do dia, nos corações ou na evolução. E dá para esconder as Travessias na própria folha do Passeio.","None of it touches your Soulmon, the daily goal, hearts or evolution. You can also hide Crossings from the Stroll sheet itself.")})]})},{id:"guild",title:X(r,"guild.guide.titulo"),body:e.jsx("p",{style:o,children:X(r,"guild.guide.corpo")})},{id:"demo",title:a("A demo","The demo"),body:e.jsx("p",{style:o,children:a(`O botão DEMO abre o jogo sem conta, com um dos cinco Soulmon iniciais no Vínculo nível ${q}. A demo salva só neste aparelho; não ganha XP (o Vínculo fica fixo), não faz compras e não entra no PvP (Torneio, Duelo, Biblioteca e Clã ficam fechados). Para ter uma conta, saia da demo em Configurações.`,`The DEMO button opens the game without an account, with one of the five starter Soulmon at Bond level ${q}. The demo saves on this device only; it earns no XP (Bond stays fixed), makes no purchases and does not enter PvP (Tournament, Duel, Library and Clan stay closed). To get an account, leave the demo in Settings.`)})},{id:"more",title:a("O resto, em uma linha cada","Everything else, one line each"),body:e.jsxs(e.Fragment,{children:[e.jsx("p",{style:o,children:a("Galhos: Poder, Harmonia e Benevolência — os requisitos são iguais nos três. No empate decide o seu ritmo de cuidado, e nenhum ritmo é melhor.","Branches: Power, Harmony and Benevolence — requirements are identical across all three. Ties are decided by your care rhythm, and no rhythm is better.")}),e.jsx("p",{style:o,children:a("Traço de nascimento: todo Soulmon nasce com um (veja em Estatísticas). Todos são positivos.","Birth trait: every Soulmon is born with one (see it in Stats). All of them are upsides.")}),e.jsx("p",{style:o,children:a("Masmorra e Torneio nunca cobram corações. Perder custa só a run.","Dungeon and Tournament never cost hearts. Losing only costs the run.")}),e.jsx("p",{style:o,children:a(`A Masmorra é uma descida automática: as lutas vêm sozinhas e a cada ${C} você desce uma camada, até a ${P}. Cada camada gasta ${d} de energia (a da Home), até ${I} camadas por dia; a descida para quando a energia, o HP ou o limite do dia acabam. O HP não enche entre descidas — volta com o tempo (uns ${U} h do zero ao cheio, até com o app fechado) e precisa de ${L}% para descer de novo. A cada ${H} camadas há um marco: a próxima descida começa dali, e o primeiro marco de cada descida rende o item 🌀 (veja Itens). Quanto mais Lv o Soulmon tem — dias completos e evolução —, mais fundo ele chega; bater uma profundidade nova (5, 10, 25, 50…) rende fragmentos do Soulsmith. Subir de nível enche a energia e o HP.`,`The Dungeon is an automatic descent: fights come on their own and every ${C} you go down a layer, all the way to ${P}. Each layer spends ${d} energy (Home energy), up to ${I} layers a day; the descent stops when energy, HP or the day's limit runs out. HP does not refill between descents — it comes back over time (about ${U} h from empty to full, even with the app closed) and you need ${L}% to go down again. Every ${H} layers is a milestone: the next descent starts there, and the first milestone of each descent earns the 🌀 item (see Items). The higher your Soulmon's Lv — complete days and evolution — the deeper it reaches; a new depth (5, 10, 25, 50…) earns Soulsmith fragments. Leveling up refills energy and HP.`)}),e.jsx("p",{style:o,children:a("Torneio e Arena são diferentes: o Torneio é RANQUEADO — o servidor sorteia seus oponentes perto da sua faixa, você não escolhe. Na Arena livre VOCÊ escolhe contra quem lutar, sempre de poder parecido com o seu.","Tournament and Arena are different: the Tournament is RANKED — the server draws your opponents near your tier and you don’t choose. In the Open Arena YOU choose who to fight, always of power similar to yours.")}),e.jsx("p",{style:o,children:a("Nos duelos (Torneio e Arena) os pets lutam sozinhos. Você torce tocando em qualquer lugar da tela: o gauge cheio vira um golpe especial. Torcer só ajuda; não torcer não atrapalha.","In duels (Tournament and Arena) the pets fight on their own. You cheer by tapping anywhere on the screen: a full gauge becomes a special strike. Cheering only helps; skipping never hurts.")}),e.jsx("p",{style:o,children:a(`Vínculo N é o seu nível como pessoa que cuida: cada Vínculo (até ${F}) rende um ponto de talento, e nenhum dinheiro compra Vínculo. A Arena e o Torneio abrem no Vínculo ${B.pvp.minBond}. Lv N é o do seu Soulmon.`,`Bond N is your own level as a carer: each Bond (up to ${F}) gives one talent point, and no money buys Bond. The Arena and the Tournament open at Bond ${B.pvp.minBond}. Lv N is your Soulmon's.`)}),e.jsx("p",{style:o,children:a(`Talentos e equipamento somam, no máximo, ${Math.round(Y*100)}% de força em qualquer luta. Cada peça de equipamento chega no nível 1 pela missão de um prédio e se aprimora no Soulsmith até o nível ${G}, com os materiais das missões; a cada nível você escolhe entre dois ganhos (refazer a escolha custa ${z} Bits ganhos jogando). Uma peça no máximo vale ${(V*100).toFixed(1).replace(".",",")}%. As peças são partes da sua alma, aprimoradas: quem a tem a traz sempre consigo, não há como tirar. Sem sorteio. Créditos aceleram só o que não é combate, em até +${Math.round(W*100)}% sobre o ritmo grátis.`,`Talents and equipment add at most ${Math.round(Y*100)}% strength in any fight. Each equipment piece arrives at level 1 through a building mission and is upgraded at the Soulsmith up to level ${G}, with the materials missions give; at each level you choose between two gains (redoing a choice costs ${z} Bits earned by playing). One piece at the top is worth ${(V*100).toFixed(1)}%. The pieces are parts of your soul, refined: once you have one it is always with you, nothing to take off. No draws. Credits speed up only what is not combat, by up to +${Math.round(W*100)}% over the free pace.`)}),e.jsx("p",{style:o,children:a("O check-in e o relatório do dia levam vinte segundos; o de domingo descreve a semana. Nada disso vira nota.","Check-in and the daily report take twenty seconds; Sunday describes the week. None of it becomes a score.")}),e.jsx("p",{style:o,children:a("Toda segunda e todo dia 1 vem um recomeço: zera as cobranças pendentes e não apaga nada do que você conquistou.","Every Monday and every 1st a fresh start is offered: pending nagging is cleared and nothing you earned is erased.")})]})}];return e.jsxs(ne,{open:Q,onClose:K,language:r,title:a("Guia","Guide"),maxWidth:520,children:[e.jsx("p",{style:m,children:a("Toque num assunto. Nada aqui é obrigatório saber para jogar.","Tap a topic. None of this is required knowledge to play.")}),e.jsx("div",{style:{display:"flex",flexDirection:"column"},children:ae.map(t=>{const n=Z===t.id;return e.jsxs("div",{children:[e.jsxs("button",{type:"button",onClick:()=>ee(n?null:t.id),"aria-expanded":n,"aria-controls":`guide-${t.id}`,className:"sm2-conta-chap",children:[e.jsx("span",{style:{flex:1,minWidth:0},children:t.title}),e.jsx(ie,{name:n?"expand_less":"expand_more",size:24,tone:n?"primary":"muted"})]}),n&&e.jsx("div",{id:`guide-${t.id}`,className:"sm2-conta-chapbody",children:t.body})]},t.id)})}),e.jsx("p",{style:m,children:a("Nos dias em que não der, seu Soulmon continua aqui.","On the days you can’t, it stays right here.")})]})}export{pe as GuideModal};
